{
  "title": "include-session-id-in-event-log-format",
  "request": "Can we add the session ID to the event pipe logs? Right now the event_handler formatter in setup_log_pipes doesn't include the session ID, making it hard to trace which session a log belongs to. Please update the formatter to embed the session ID.",
  "edits": [
    {
      "path": "browser_use/logging_config.py",
      "search": "event_handler.setFormatter(logging.Formatter('%(levelname)-8s [%(name)s] %(message)s'))",
      "replace": "event_handler.setFormatter(logging.Formatter(f'%(levelname)-8s [%(name)s] [session:{session_id}] %(message)s'))"
    }
  ],
  "test_path": "tests/test_logging_config_session_id.py",
  "test": "import logging\nfrom browser_use.logging_config import setup_log_pipes\n\ndef test_event_handler_formatter_includes_session_id(tmp_path):\n    session_id = \"test1234\"\n    # Initialize the pipe handlers using a temporary base directory to avoid filesystem side effects\n    setup_log_pipes(session_id=session_id, base_dir=str(tmp_path))\n    logger = logging.getLogger('browser_use.browser.session')\n    # Collect format strings from attached handlers\n    fmt_strings = [handler.formatter._fmt for handler in logger.handlers if getattr(handler, 'formatter', None)]\n    # Ensure at least one formatter includes the session ID\n    assert any(f\"session:{session_id}\" in fmt for fmt in fmt_strings), \"Session ID not found in event handler formatter\"\n"
}
